// Typed API client for the CellBench backend.
//
// Generated by hand in v1; in v2 this file is produced from the FastAPI
// OpenAPI schema via `openapi-typescript`.

export type UUID = string;

export interface User {
  id: UUID;
  email: string;
  full_name: string;
  role: "user" | "admin";
  created_at: string;
}

export interface Dataset {
  id: UUID;
  slug: string;
  name: string;
  description: string;
  organism: string | null;
  modality: string | null;
  n_cells: number | null;
  n_genes: number | null;
  storage_uri: string;
  extra: Record<string, unknown>;
  created_at: string;
}

export interface Challenge {
  id: UUID;
  slug: string;
  title: string;
  description_md: string;
  dataset_id: UUID;
  metric: string;
  eval_split: Record<string, unknown>;
  deadline: string | null;
  is_open: boolean;
  created_at: string;
}

export interface LeaderboardRow {
  rank: number;
  user_id: UUID;
  user_email: string;
  submission_id: UUID;
  score: number;
  scored_at: string;
  model_name: string | null;
  model_version: string | null;
}

export interface Submission {
  id: UUID;
  challenge_id: UUID;
  model_version_id: UUID | null;
  status: "pending_upload" | "queued" | "scoring" | "scored" | "failed";
  submitted_at: string;
  scored_at: string | null;
  error_message: string | null;
}

export interface Model {
  id: UUID;
  name: string;
  description: string;
  created_at: string;
}

const API_BASE =
  process.env.API_URL ??
  process.env.NEXT_PUBLIC_API_URL ??
  "http://localhost:8000";

function authHeader(token: string | null): Record<string, string> {
  return token ? { Authorization: `Bearer ${token}` } : {};
}

async function request<T>(
  path: string,
  init: RequestInit & { token?: string | null } = {},
): Promise<T> {
  const { token, headers, ...rest } = init;
  const res = await fetch(`${API_BASE}${path}`, {
    ...rest,
    headers: {
      "Content-Type": "application/json",
      ...authHeader(token ?? null),
      ...(headers ?? {}),
    },
    cache: "no-store",
  });
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`API ${res.status}: ${text}`);
  }
  return (await res.json()) as T;
}

export const api = {
  // Auth
  register: (body: { email: string; password: string; full_name?: string }) =>
    request<{ access_token: string }>("/v1/auth/register", {
      method: "POST",
      body: JSON.stringify(body),
    }),
  login: (body: { email: string; password: string }) =>
    request<{ access_token: string }>("/v1/auth/login", {
      method: "POST",
      body: JSON.stringify(body),
    }),
  me: (token: string) => request<User>("/v1/auth/me", { token }),

  // Datasets
  listDatasets: (params: { organism?: string; modality?: string; q?: string } = {}) => {
    const qs = new URLSearchParams(
      Object.entries(params).filter(([, v]) => v) as [string, string][],
    );
    return request<Dataset[]>(`/v1/datasets?${qs.toString()}`);
  },
  getDataset: (slug: string) => request<Dataset>(`/v1/datasets/${slug}`),

  // Challenges
  listChallenges: () => request<Challenge[]>("/v1/challenges"),
  getChallenge: (slug: string) => request<Challenge>(`/v1/challenges/${slug}`),
  leaderboard: (slug: string) =>
    request<LeaderboardRow[]>(`/v1/challenges/${slug}/leaderboard`),

  // Submissions
  createSubmission: (
    token: string,
    body: { challenge_id: UUID; model_version_id?: UUID; filename: string },
  ) =>
    request<{ submission_id: UUID; upload_url: string; object_key: string }>(
      "/v1/submissions",
      { method: "POST", body: JSON.stringify(body), token },
    ),
  completeSubmission: (token: string, id: UUID) =>
    request<Submission>(`/v1/submissions/${id}/complete`, {
      method: "POST",
      token,
    }),
  mySubmissions: (token: string) =>
    request<Submission[]>("/v1/submissions/mine", { token }),

  // Models
  listModels: (token: string) => request<Model[]>("/v1/models", { token }),
  createModel: (token: string, body: { name: string; description?: string }) =>
    request<Model>("/v1/models", {
      method: "POST",
      body: JSON.stringify(body),
      token,
    }),
};
